for (const id of ['row-print', 'row-audio']) {
  const row = document.getElementById(id);
  if (!row) return false;
  const r = row.getBoundingClientRect();
  if (r.height < 20) return false;
  for (const a of row.querySelectorAll('a, strong')) {
    const b = a.getBoundingClientRect();
    if (b.top < r.top - 1 || b.bottom > r.bottom + 1) return false;
  }
}
return true;

const first = document.getElementById('print-list');
const second = document.querySelector('#row-audio a');
if (!first || !second) return false;
return second.getBoundingClientRect().top >= first.getBoundingClientRect().bottom - 1;

const tabs = [...document.querySelectorAll('#tabs li')];
if (tabs.length !== 4) return false;
const top = tabs[0].getBoundingClientRect().top;
return tabs.every((t) => Math.abs(t.getBoundingClientRect().top - top) < 2);

const list = document.getElementById('account');
if (!list) return false;
if (getComputedStyle(list).float === 'none') return false;
const items = [...list.querySelectorAll('li')];
return items.length === 2 && Math.abs(items[0].getBoundingClientRect().top - items[1].getBoundingClientRect().top) < 2;

const story = document.getElementById('story');
const related = document.getElementById('related');
if (!story || !related) return false;
if (!document.documentElement.classList.contains('ai4a11y-reflow')) return getComputedStyle(story).float === 'left';
if (getComputedStyle(story).float !== 'none' || getComputedStyle(related).float !== 'none') return false;
return related.getBoundingClientRect().top >= story.getBoundingClientRect().bottom - 5;
